      "arFull": "فَجَآءَتْهُ اِحْدٰىهُمَا تَمْشِیْ عَلَی اسْتِحْیَآءٍ ؗ قَالَتْ اِنَّ اَبِیْ یَدْعُوْكَ لِیَجْزِیَكَ اَجْرَ مَا سَقَیْتَ لَنَا ؕ فَلَمَّا جَآءَهٗ وَقَصَّ عَلَیْهِ الْقَصَصَ ۙ قَالَ لَا تَخَفْ ۫ۥ نَجَوْتَ مِنَ الْقَوْمِ الظّٰلِمِیْنَ ۟",
      "ur": "اتنے میں ان دونوں عورتوں میں سے ایک ان کی طرف شرم وحیا سے چلتی ہوئی آئی[1] ، کہنے لگی کہ میرے باپ آپ کو بلا رہے ہیں تاکہ آپ نے ہمارے (جانوروں) کو جو پانی پلایا ہے اس کی اجرت دیں[2]، جب حضرت موسیٰ (علیہ السلام) ان کے پاس پہنچے اور ان سے اپنا سارا حال بیان کیا تو وه کہنے لگے اب نہ ڈر تو نے ﻇالم قوم سے نجات پائی.[3]",
      "en": "Then one of the two women came to him walking with shyness. She said, \"Indeed, my father invites you that he may reward you for having watered for us.\" So when he came to him[1099] and related to him the story, he said, \"Fear not. You have escaped from the wrongdoing people.\"",
      "footnotesUr": "[1] اللہ نے حضرت موسیٰ (عليه السلام) کی دعا قبول فرما لی اور دونوں میں سے ایک لڑکی انہیں بلانے آگئی۔ لڑکی کی شرم وحیا کا قرآن نے بطور خاص ذکر کیا ہے کہ یہ عورت کا اصل زیور ہے۔ اور مردوں کی طرح حیا وحجاب سے بے نیازی اور بے باکی عورت کے لیے شرعاً ناپسندیدہ ہے۔\n[2] بچیوں کا باپ کون تھا؟ قرآن کریم نے صراحت سے کسی کا نام نہیں لیا ہے۔ مفسرین کی اکثریت نے اس سے مراد حضرت شعیب (عليه السلام) کو لیا ہے جو اہل مدین کی طرف مبعوث ہوئے تھے۔ امام شوکانی نے بھی اسی قول کو ترجیح دی ہے۔ لیکن امام ابن کثیر فرماتے ہیں کہ حضرت شعیب (عليه السلام) کا زمانہ نبوت، حضرت موسیٰ (عليه السلام) سے بہت پہلے کا ہے۔ اس لیے یہاں حضرت شعیب (عليه السلام) کا برادر زادہ یا کوئی اور قوم شعیب (عليه السلام) کا شخص مراد ہے، واللہ اعلم۔ بہرحال حضرت موسیٰ (عليه السلام) نے بچیوں کے ساتھ جو ہمدردی اور احسان کیا، وہ بچیوں نے جاکر بوڑھے باپ کو بتلایا، جس سے باپ کے دل میں بھی داعیہ پیدا ہوا کہ احسان کا بدلہ احسان کے ساتھ دیا جائے یا اس کی محنت کی اجرت ہی ادا کر دی جائے۔\n[3] یعنی اپنے مصر کی سرگزشت اور فرعون کے ظلم وستم کی تفصیل سنائی جس پر انہوں نے کہا کہ یہ علاقہ فرعون کی حدود حکمرانی سے باہر ہے اس لیے ڈرنے کی ضرورت نہیں ہے۔ اللہ نے ظالموں سے نجات عطا فرما دی ہے۔",
