      "number": 26,
      "arFull": "قَالَتْ اِحْدٰىهُمَا یٰۤاَبَتِ اسْتَاْجِرْهُ ؗ اِنَّ خَیْرَ مَنِ اسْتَاْجَرْتَ الْقَوِیُّ الْاَمِیْنُ ۟",
      "ur": "ان دونوں میں سے ایک نے کہا کہ ابا جی! آپ انہیں مزدوری پر رکھ لیجئے، کیونکہ جنہیں آپ اجرت پر رکھیں ان میں سے سب سے بہتر وه ہے جو مضبوط اور امانت دار ہو.[1]",
      "en": "One of the women said, \"O my father, hire him. Indeed, the best one you can hire is the strong and the trustworthy.\"",
      "footnotesUr": "[1] بعض مفسرین نے لکھا ہے کہ باپ نے بچیوں سے پوچھا تمہیں کس طرح معلوم ہے کہ یہ طاقت ور بھی ہے اور امانت دار بھی۔ جس پر بچیوں نے بتلایا کہ جس کنویں سے پانی پلایا، اس پر اتنا بھاری پتھر رکھا ہوتا ہے کہ اسے اٹھانے کے لیے دس آدمیوں کی ضرورت ہوتی ہے لیکن ہم نے دیکھا کہ اس شخص نے وہ پتھر اکیلے ہی اٹھا لیا اور پھر بعد میں رکھ دیا۔ اسی طرح جب میں اس کو بلا کر اپنے ساتھ لا رہی تھی، تو چونکہ راستے کا علم مجھے ہی تھا، میں آگے آگے چل رہی تھی اور یہ پیچھے پیچھے۔ لیکن ہوا سے میری چادر اڑ جاتی تھی تو اس شخص نے کہا کہ تو پیچھے چل، میں آگے آگے چلتا ہوں تاکہ میری نگاہ تیرے جسم کے کسی حصے پر نہ پڑے۔ راستے کی نشاندہی کے لیے پیچھے سے پتھر، کنکری مار دیا کر، وَاللهُ أَعْلَمُ بِحَالِ صِحَّتِهِ۔ (ابن کثیر)",
