      "number": 27,
      "arFull": "قَالَ اِنِّیْۤ اُرِیْدُ اَنْ اُنْكِحَكَ اِحْدَی ابْنَتَیَّ هٰتَیْنِ عَلٰۤی اَنْ تَاْجُرَنِیْ ثَمٰنِیَ حِجَجٍ ۚ فَاِنْ اَتْمَمْتَ عَشْرًا فَمِنْ عِنْدِكَ ۚ وَمَاۤ اُرِیْدُ اَنْ اَشُقَّ عَلَیْكَ ؕ سَتَجِدُنِیْۤ اِنْ شَآءَ اللّٰهُ مِنَ الصّٰلِحِیْنَ ۟",
      "ur": "اس بزرگ نے کہا میں اپنی ان دونوں لڑکیوں میں سے ایک کو آپ کے نکاح میں دینا چاہتا ہوں[1] اس (مہر پر) کہ آپ آٹھ سال تک میرا کام کاج کریں[2]۔ ہاں اگر آپ دس سال پورے کریں تو یہ آپ کی طرف سے بطور احسان کے ہے میں یہ ہرگز نہیں چاہتا کہ آپ کو کسی مشقت میں ڈالوں[3]، اللہ کو منظور ہے تو آگے چل کر آپ مجھے بھلا آدمی پائیں گے.[4]",
      "en": "He said, \"Indeed, I wish to wed you one of these, my two daughters, on [the condition] that you serve me for eight years; but if you complete ten, it will be [as a favor] from you. And I do not wish to put you in difficulty. You will find me, if Allāh wills, from among the righteous.\"",
      "footnotesUr": "[1] ہمارے ملک میں کسی لڑکی والے کی طرف سے نکاح کی خواہش کا اظہار معیوب سمجھا جاتا ہے۔ لیکن شریعت الٰہیہ میں یہ مذموم نہیں ہے۔ صفات محمودہ کا حامل لڑکا اگر مل جائے تو اس سے یا اس کے گھر والوں سے اپنی لڑکی کے لیے رشتے کی بابت بات چیت کرنا برا نہیں ہے، بلکہ محمود اور پسندیدہ ہے۔ عہد رسالت مآب (صلى الله عليه وسلم) اور صحابہ کرام رضوان اللہ علیہم اجمعین میں بھی یہی طریقہ تھا۔\n[2] اس سے علما نے اجارے کے جواز پر استدلال کیا ہے یعنی کرائے اور اجرت پر مرد کی خدمات حاصل کرنا جائز ہے۔\n[3] یعنی مزید دو سال کی خدمت میں مشقت اور ایذا محسوس کریں تو آٹھ سال کے بعد جانے کی اجازت ہوگی۔\n[4] نہ جھگڑا کروں گا نہ اذیت پہنچاؤں گا، نہ سختی سے کام لوں گا۔",
