      "number": 70,
      "arFull": "وَهُوَ اللّٰهُ لَاۤ اِلٰهَ اِلَّا هُوَ ؕ لَهُ الْحَمْدُ فِی الْاُوْلٰی وَالْاٰخِرَةِ ؗ وَلَهُ الْحُكْمُ وَاِلَیْهِ تُرْجَعُوْنَ ۟",
